if(!defined('ABSPATH'))return;
add_action('wp_loaded', function(){
  if(($_GET['ps_snipdb']??'')!=='S636x') return;
  if(!( current_user_can('manage_options') || (($_GET['k']??'')==='ps2026') )) return;
  global $wpdb; $t = $wpdb->prefix.'snippets'; $out = array('v'=>'SNIPDB-V1');
  $out['table'] = $t;
  $out['exists'] = (bool) $wpdb->get_var("SHOW TABLES LIKE '$t'");
  if(!$out['exists']){ header('Content-Type:application/json'); echo wp_json_encode($out); exit; }
  $out['total']  = (int) $wpdb->get_var("SELECT COUNT(*) FROM $t");
  $out['active'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM $t WHERE active=1");
  // TRYNIMO KANDIDATAI: neaktyvūs IR pavadinime TEMP / (temp) / tmp
  $where = "active=0 AND ( name LIKE 'TEMP%' OR name LIKE '%(temp)%' OR name LIKE '% tmp%' OR name LIKE '%tmp %' OR name LIKE '%TEMP %' OR name LIKE '%(tmp)%' )";
  $out['kandidatai'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM $t WHERE $where");
  $out['kand_pvz']   = $wpdb->get_results("SELECT id,name,active FROM $t WHERE $where ORDER BY id LIMIT 25", ARRAY_A);
  // SAUGIKLIS: ar tarp kandidatų nėra aktyvių arba svarbių ID
  $out['saugiklis_aktyvus_tarp_kand'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM $t WHERE ($where) AND active=1");
  $keep = array(2384,2387,492,493,1357,1358,707,2051,472,469);
  $out['saugiklis_svarbus'] = $wpdb->get_col("SELECT id FROM $t WHERE ($where) AND id IN (".implode(',',$keep).")");
  // LIKUTIS po hipotetinio trynimo
  $out['liktu'] = $out['total'] - $out['kandidatai'];
  // neaktyvūs BE temp požymio (jų neliesim)
  $out['neaktyvus_be_temp'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM $t WHERE active=0 AND NOT ( $where )");
  // ar yra backup lentelė
  $b = $t.'_bak_s636';
  $out['backup_yra'] = (bool) $wpdb->get_var("SHOW TABLES LIKE '$b'");
  if(($_GET['do']??'')==='backup' && !$out['backup_yra']){
    $wpdb->query("CREATE TABLE $b LIKE $t");
    $wpdb->query("INSERT INTO $b SELECT * FROM $t");
    $out['backup_sukurta'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM $b");
  } elseif($out['backup_yra']) {
    $out['backup_eiluciu'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM $b");
  }
  header('Content-Type:application/json; charset=utf-8');
  echo wp_json_encode($out, JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
}, 6);

