add_action('wp_loaded', function(){
  $v = isset($_GET['ps_fix2']) ? sanitize_key($_GET['ps_fix2']) : '';
  if ($v==='') return;
  if (!headers_sent()) { nocache_headers(); header('Content-Type: application/json; charset=utf-8'); }
  @set_time_limit(280);
  global $wpdb; $p=$wpdb->prefix;
  $r=array('VERSIJA'=>'s630','veiksmas'=>$v);

  $neigiami = array(16317,17443,18623,17710);   // likutis i 0
  $josera   = 17978;                             // atstatyti is VF

  $busena = function($pid) use ($p,$wpdb) {
    return array(
      'id'=>$pid,
      'pav'=>mb_substr(html_entity_decode(get_the_title($pid)),0,46),
      'stock'=>get_post_meta($pid,'_stock',true),
      'stock_status'=>get_post_meta($pid,'_stock_status',true),
      'own_stock_qty'=>get_post_meta($pid,'_own_stock_qty',true),
      'vf_qty'=>get_post_meta($pid,'_vf_qty',true),
      'sandelis'=>get_post_meta($pid,'_ps_sandelis',true),
      'sources'=>$wpdb->get_results($wpdb->prepare(
        "SELECT source,stock_qty,priority FROM {$p}ps_sources WHERE product_id=%d ORDER BY priority",$pid),ARRAY_A),
    );
  };

  $visi = array_merge($neigiami, array($josera));
  $r['PRIES'] = array_map($busena, $visi);

  if ($v === 'dry') {
    $r['PLANAS'] = array(
      'neigiami' => 'keturioms prekems _stock -> 0 (stock_status lieka outofstock)',
      'josera'   => 'istrinti _own_stock_qty (artefaktas), _stock -> _vf_qty ('.get_post_meta($josera,'_vf_qty',true).'), stock_status -> instock',
      'sources'  => 'ps_sources eilutes perskaiciuojamos is naujo',
    );
    $r['PASTABA']='Nieko nekeista.';
    echo wp_json_encode($r,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
  }

  if ($v === 'apply') {
    if (!isset($_GET['patvirtinu']) || $_GET['patvirtinu']!=='taip') {
      $r['KLAIDA']='truksta &patvirtinu=taip';
      echo wp_json_encode($r,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
    }
    $log=array();

    // 1) Neigiami -> 0
    foreach ($neigiami as $pid) {
      $buvo = get_post_meta($pid,'_stock',true);
      update_post_meta($pid,'_stock','0');
      $pr = wc_get_product($pid);
      if ($pr) { $pr->set_stock_quantity(0); $pr->set_stock_status('outofstock'); $pr->save(); }
      $log[]=array('id'=>$pid,'veiksmas'=>'likutis '.$buvo.' -> 0');
    }

    // 2) Josera: pasalinti artefakta ir atstatyti is VF
    $vfq = (int) get_post_meta($josera,'_vf_qty',true);
    $buvo = get_post_meta($josera,'_stock',true);
    $ownb = get_post_meta($josera,'_own_stock_qty',true);
    delete_post_meta($josera,'_own_stock_qty');
    update_post_meta($josera,'_stock', (string)$vfq);
    $pr = wc_get_product($josera);
    if ($pr) { $pr->set_stock_quantity($vfq); $pr->set_stock_status($vfq>0?'instock':'outofstock'); $pr->save(); }
    $log[]=array('id'=>$josera,'veiksmas'=>'_own_stock_qty ('.$ownb.') istrintas · likutis '.$buvo.' -> '.$vfq.' (is _vf_qty)');

    // 3) ps_sources perskaiciavimas
    if (class_exists('Petshop_Sources')) {
      $t = Petshop_Sources::lentele(); $now = current_time('mysql');
      foreach ($visi as $pid) {
        $wpdb->delete($t, array('product_id'=>$pid));
        foreach (Petshop_Sources::suskaiciuoti($pid) as $x) {
          $wpdb->insert($t, array(
            'product_id'=>$pid,'source'=>$x['source'],'supplier_sku'=>$x['supplier_sku'],
            'ean'=>$x['ean'],'stock_qty'=>$x['stock_qty'],'cost_net'=>$x['cost_net'],
            'synced_at'=>$x['synced_at'],'is_active'=>$x['is_active'],'is_sellable'=>$x['is_sellable'],
            'priority'=>$x['priority'],'created_at'=>$now,'updated_at'=>$now));
        }
      }
      $log[]=array('id'=>'ps_sources','veiksmas'=>'perskaiciuota '.count($visi).' prekems');
    }
    $r['ATLIKTA']=$log;

    // 4) PATIKRA
    $r['PO'] = array_map($busena, $visi);
    $r['likusiu_neigiamu'] = (int)$wpdb->get_var(
      "SELECT COUNT(*) FROM {$p}postmeta m JOIN {$p}posts po ON po.ID=m.post_id AND po.post_type='product'
       WHERE m.meta_key='_stock' AND m.meta_value+0<0");
    $r['own_stock_qty_liko'] = (int)$wpdb->get_var(
      "SELECT COUNT(*) FROM {$p}postmeta WHERE meta_key='_own_stock_qty'");
    if (class_exists('Petshop_Stock_Service')) {
      $r['stock_service_josera'] = Petshop_Stock_Service::parduodama($josera);
    }
    echo wp_json_encode($r,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
  }
  $r['KLAIDA']='nezinomas veiksmas';
  echo wp_json_encode($r,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
},1);
